-- =========================================================================
-- NAUKA Pagos — BUY-OUT · Etapa 2b: VOLCADO de conceptos/cotizaciones de BF
-- =========================================================================
-- Carga los conceptos, cotizaciones y renglones REALES de Beachfront desde
-- reference/NAUKA - BUY OUT BF 290626.xlsx (valores calculados, no fórmulas),
-- usando el MISMO parseo del preview (docs/buyout-bf-volcado-preview.md, 30/30).
-- Grano = total del proyecto. Decisiones de Alfonso:
--   • Concepto fino del tab = un buyout_item (Iluminacion 30 cuartos, etc.).
--   • CONTINGENCIAS = capítulo+partida propios al FINAL (orden 12 / 31).
--   • quote_date default = 2026-06-29 (fecha del archivo). Proveedor NA -> kind=parametrico.
--   • 'REJILLAS?' se carga tal cual y se marca en notas.
--
-- MODELO: el rollup (lib/buyout/rollup.ts) suma SOLO las lineas de la cotizacion
-- VIGENTE de cada item; por el indice unico (1 vigente por item) cada concepto
-- tiene UNA cotizacion vigente que agrupa TODAS sus lineas (proveedor por-linea
-- en buyout_line.proveedor). El total NO se almacena: la app lo recomputa
-- (cantidad*unitario*(1+sobrecosto)*(1+iva)*tc, tc=fx[moneda]).
--
-- CUADRE: como unitario es numeric(14,2), 6 partidas con unitarios de muchos
-- decimales (USD/computados) driftarian centavos al recomputar. Para cuadrar AL
-- CENTAVO con el preview, en esas 6 partidas la linea de mayor monto se almacena
-- en MXN (cant=1, sobrecosto=0, iva=0, unitario = su total + residual) absorbiendo
-- el residual; su TOTAL se preserva. Las demas lineas quedan fieles. Verificado
-- transaccionalmente abajo (rollback si alguna partida no cuadra).
--
-- AISLAMIENTO: TODO filtra por project_id de 'NAUKA Beachfront'. Idempotente:
-- borra primero el transaccional de BF (hard delete, seguro: etapa 2 nunca escribio).
-- NO toca L3, ni Pagos, ni proveedores existentes. Suppliers son GLOBALES (se crean
-- si faltan). Auto-verificado (DO-blocks) -> cualquier descuadre/afectacion a L3 => rollback.
-- =========================================================================

-- 0. Guard: BF existe.
DO $$
DECLARE bf uuid;
BEGIN
  SELECT id INTO bf FROM public.projects WHERE nombre='NAUKA Beachfront' AND deleted_at IS NULL;
  IF bf IS NULL THEN RAISE EXCEPTION 'NAUKA Beachfront no encontrado'; END IF;
END $$;

-- 1. Limpieza idempotente del transaccional de BF (hard delete; CASCADE quote->line).
DELETE FROM public.buyout_item  WHERE project_id=(SELECT id FROM public.projects WHERE nombre='NAUKA Beachfront' AND deleted_at IS NULL);
DELETE FROM public.buyout_falta WHERE project_id=(SELECT id FROM public.projects WHERE nombre='NAUKA Beachfront' AND deleted_at IS NULL);
DELETE FROM public.buyout_import_batch WHERE project_id=(SELECT id FROM public.projects WHERE nombre='NAUKA Beachfront' AND deleted_at IS NULL);

-- 2. CONTINGENCIAS: capitulo (orden 12, tras OTROS) + partida (orden 31) + base 0 + concepto. Idempotente.
WITH bf AS (SELECT id FROM public.projects WHERE nombre='NAUKA Beachfront' AND deleted_at IS NULL)
SELECT bf.id, 'CONTINGENCIAS', 12 FROM bf
WHERE NOT EXISTS (SELECT 1 FROM public.buyout_chapter c JOIN bf ON c.project_id=bf.id WHERE c.nombre='CONTINGENCIAS' AND c.deleted_at IS NULL);

WITH bf AS (SELECT id FROM public.projects WHERE nombre='NAUKA Beachfront' AND deleted_at IS NULL)
SELECT bf.id, 'CONTINGENCIAS', 'CONTINGENCIAS', 31 FROM bf
WHERE NOT EXISTS (SELECT 1 FROM public.buyout_partida_catalog p JOIN bf ON p.project_id=bf.id WHERE p.nombre='CONTINGENCIAS' AND p.deleted_at IS NULL);

WITH bf AS (SELECT id FROM public.projects WHERE nombre='NAUKA Beachfront' AND deleted_at IS NULL)
SELECT bf.id, p.id, 0 FROM bf JOIN public.buyout_partida_catalog p ON p.project_id=bf.id AND p.nombre='CONTINGENCIAS' AND p.deleted_at IS NULL
WHERE NOT EXISTS (SELECT 1 FROM public.buyout_partida_base b WHERE b.partida_catalog_id=p.id AND b.deleted_at IS NULL);

