-- 5. Staging temporal con los renglones del volcado (valores ya resueltos/colapsados).
CREATE TEMP TABLE _bf_load (
  partida text, concepto text, line_seq int,
  detalle text, torre text, piso text, depto text, proveedor text, unidad text,
  cantidad numeric, moneda text, unitario numeric, sobrecosto numeric, iva numeric, notas text,
  q_currency text, q_kind text, q_contratado boolean, q_supplier text, q_iva numeric, q_monto numeric
) ON COMMIT DROP;


